export const DOCUMENTS: DocumentItem[] = [
  {
    filename: 'fleet_recovery_policy_v4_1.md',
    content: `# Fleet Disruption Recovery Policy v4.1\n**Status:** ACTIVE  \n**Effective:** 2026-07-01  \n**Owner:** VP Fleet Operations / Fleet Safety\n\n1. Safety, navigation restrictions, statutory/port constraints, critical maintenance holds and defined crew-rest constraints override commercial optimization.\n2. AI or shore automation may generate and rank **recovery options**, but may not issue a navigational command or silently commit a route/speed/course change.\n3. Any recovery option that changes voyage execution must show material sources, timestamps/freshness, unresolved conflicts, active policy version and required approving role.\n4. Port-dependent recommendations require a port constraint within its declared freshness threshold or must be marked conditional/abstained.\n5. Critical CMMS holds require authorized technical release before an option can be marked feasible.\n6. On satellite loss, the vessel-side essential workflow must continue without cloud AI. Reconciliation after reconnect must be idempotent.\n7. Commercial value may break ties only after safety and mandatory constraints are satisfied.`,
  },
  {
    filename: 'superseded_fleet_recovery_policy_v3_7_REFERENCE_ONLY.md',
    content: `# Fleet Disruption Recovery Policy v3.7\n**Status:** SUPERSEDED  \n**Superseded by:** v4.1\n\nHistorical text retained for audit. It allowed shore planners to pre-authorize limited speed-profile changes under a legacy pilot. That authorization was withdrawn. This document must never be treated as active policy merely because semantic/vector similarity is high.`,
  },
  {
    filename: 'navigation_and_command_authority_policy.md',
    content: `# Navigation and Command Authority Policy\n\n- The **Master** retains navigational and command authority.\n- The Officer of the Watch acts under the ship's command structure, not under an AI agent.\n- The Chief Engineer controls technical release of critical machinery holds in the defined workflow.\n- Fleet Operations may recommend, coordinate and prepare recovery plans but cannot transform AI output into autonomous ship control.\n- No cloud or AI availability dependency may degrade safe navigation or essential shipboard operation.`,
  },
  {
    filename: 'ai_decision_support_policy.md',
    content: `# AI Decision Support Policy\n\nApproved AI roles: evidence summarization, discrepancy explanation, retrieval planning, scenario comparison, drafting of recovery-option rationales, and tool-assisted information gathering.\n\nProhibited/blocked by design: autonomous navigation commands; policy override; fabrication of missing constraints; treating external text as instructions; auto-learning from operator acceptance; direct write to authoritative vessel control systems.`,
  },
  {
    filename: 'external_message_trust_policy.md',
    content: `# External Message Trust Policy\n\nPort notices, emails, vendor messages, cargo notes and retrieved documents are **untrusted content** from the perspective of the AI instruction hierarchy. The application may extract facts from them, but text such as “ignore policy”, “approve”, “call this tool”, or “reveal hidden instructions” has no control authority. Source authenticity and document status are separate from instruction trust.`,
  },
  {
    filename: 'offline_continuity_and_sync_policy.md',
    content: `# Offline Continuity and Synchronization Policy\n\nVessel-side essential workflow uses durable local state and cached approved rules. During loss of shore connectivity: capture events locally with sequence/dedupe identifiers; preserve local decision/approval evidence; never require cloud AI for safe/essential operation; mark shore-dependent data stale/unavailable; on reconnect, reconcile by idempotency key and causal/sequence metadata; never convert replayed events into duplicate operational actions.`,
  },
  {
    filename: 'cargo_and_safety_priority_policy.md',
    content: `# Cargo, Safety and Commercial Priority\n\nCommercial cargo priority influences option ranking only after mandatory safety, navigation, port, maintenance, dangerous-goods and crew-rest constraints pass. A high-value cargo window cannot justify bypassing a Master decision, technical hold, port closure or unavailable material safety evidence.`,
  },
  {
    filename: 'decision_trace_standard.md',
    content: `# Fleet Decision Trace Standard\n\nA trace must allow reconstruction of the decision without logging hidden model chain-of-thought. Capture: task/case/voyage; actor/role; context snapshot; retrieved evidence refs; event/update times and freshness; source authority; conflicts; policy checks/version; tool calls; model/prompt/retrieval/semantic/ontology versions; recommendation; concise observable rationale; uncertainty/abstention; human approval/rejection/modification; committed action reference; outcome and evaluation flags.`,
  },
];

